const WeeklyScheduleGrid = (props) => {
  const { weekStartISO, days, sessions, timezone, summary } = props;

  const safeDays = (() => {
    const n = Number(days);
    if (isNaN(n) || n <= 0) return 7;
    return Math.min(Math.max(n, 1), 14);
  })();

  const startDate = weekStartISO ? new Date(weekStartISO) : null;
  const startValid = startDate instanceof Date && !isNaN(startDate?.getTime());

  const dayItems = React.useMemo(() => {
    if (!startValid) return [];
    const arr = [];
    for (let i = 0; i < safeDays; i++) {
      const d = new Date(startDate);
      d.setDate(d.getDate() + i);
      arr.push(d);
    }
    return arr;
  }, [startValid, weekStartISO, safeDays]);

  const locale = undefined;

  const formatDayHeader = (d) => {
    try {
      const weekday = d.toLocaleDateString(locale, { weekday: 'short' });
      const datePart = d.toLocaleDateString(locale, { month: 'short', day: 'numeric' });
      return `${weekday} ${datePart}`;
    } catch (e) {
      return d.toDateString();
    }
  };

  const todayKey = new Date().toDateString();

  const rangeLabel = React.useMemo(() => {
    if (!startValid || dayItems.length === 0) return '';
    const first = dayItems[0];
    const last = dayItems[dayItems.length - 1];
    try {
      const firstStr = first.toLocaleDateString(locale, { month: 'short', day: 'numeric', year: 'numeric' });
      const lastStr = last.toLocaleDateString(locale, { month: 'short', day: 'numeric', year: 'numeric' });
      return `${firstStr} — ${lastStr}`;
    } catch (e) {
      return `${first.toDateString()} — ${last.toDateString()}`;
    }
  }, [dayItems, startValid]);

  const hasSessions = Array.isArray(sessions) && sessions.length > 0;

  if (!startValid) {
    return (
      <div className="w-full max-w-2xl mx-auto bg-white rounded-lg shadow-sm border border-gray-200 p-4">
        <div className="flex items-start justify-between mb-2">
          <h3 className="text-lg font-semibold text-gray-900">Weekly Schedule</h3>
          {timezone && (
            <span className="ml-2 px-2 py-1 text-xs font-medium bg-blue-50 text-blue-700 rounded">TZ: {timezone}</span>
          )}
        </div>
        {summary && <p className="text-sm text-gray-600 mb-3 line-clamp-2">{summary}</p>}
        <div className="p-4 bg-gray-50 border border-gray-200 rounded-md">
          <div className="text-sm text-gray-700">Invalid start date</div>
          <div className="text-xs text-gray-500 mt-1">Provided weekStartISO: {weekStartISO || 'None'}</div>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-lg shadow-sm border border-gray-200 p-4 hover:shadow-md transition-shadow duration-200">
      <div className="flex items-start justify-between mb-2">
        <h3 className="text-lg font-semibold text-gray-900">Weekly Schedule</h3>
        <div className="flex items-center space-x-2">
          {timezone && (
            <span className="px-2 py-1 text-xs font-medium bg-blue-50 text-blue-700 rounded">TZ: {timezone}</span>
          )}
          {rangeLabel ? (
            <span className="px-2 py-1 text-xs font-medium bg-gray-100 text-gray-700 rounded">{rangeLabel}</span>
          ) : null}
        </div>
      </div>
      {summary && <p className="text-sm text-gray-600 mb-3 line-clamp-2">{summary}</p>}
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-3 py-2 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">Session</th>
              {dayItems.map((d, idx) => {
                const isToday = d.toDateString() === todayKey;
                return (
                  <th
                    key={idx}
                    className={
                      "px-3 py-2 text-left text-xs font-semibold uppercase tracking-wider " +
                      (isToday ? "text-blue-700" : "text-gray-700")
                    }
                  >
                    <div className="flex items-center space-x-2">
                      <span>{formatDayHeader(d)}</span>
                      {isToday ? <span className="px-1.5 py-0.5 text-[10px] bg-blue-100 text-blue-700 rounded">Today</span> : null}
                    </div>
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-100">
            {hasSessions ? (
              sessions.map((label, rIdx) => (
                <tr key={rIdx} className={rIdx % 2 === 0 ? "bg-white" : "bg-gray-50"}>
                  <td className="px-3 py-2 text-sm text-gray-800">
                    <span className="inline-flex items-center px-2 py-0.5 bg-gray-100 text-gray-700 rounded">
                      {label || 'Session'}
                    </span>
                  </td>
                  {dayItems.map((d, cIdx) => {
                    const isToday = d.toDateString() === todayKey;
                    return (
                      <td key={cIdx} className="px-3 py-3 text-sm">
                        <div
                          className={
                            "w-full h-10 rounded-md border " +
                            (isToday ? "border-blue-200 bg-blue-50" : "border-gray-200 bg-gray-50")
                          }
                        >
                          <div className="h-full flex items-center justify-center">
                            <span className={isToday ? "text-blue-600 text-xs" : "text-gray-500 text-xs"}>
                              —
                            </span>
                          </div>
                        </div>
                      </td>
                    );
                  })}
                </tr>
              ))
            ) : (
              <tr>
                <td className="px-3 py-6 text-sm text-gray-600" colSpan={dayItems.length + 1}>
                  <div className="flex items-center space-x-3">
                    <div className="w-8 h-8 rounded-full bg-gray-100 flex items-center justify-center">
                      <span className="text-gray-400">🗓️</span>
                    </div>
                    <div>
                      <div className="text-gray-800 font-medium">No sessions to display</div>
                      <div className="text-xs text-gray-500">Add session labels to see them in this week’s grid.</div>
                    </div>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
      <div className="mt-3 flex items-center justify-between">
        <div className="text-xs text-gray-500">
          Start: {dayItems[0] ? dayItems[0].toLocaleDateString() : '—'}
        </div>
        <div className="text-xs text-gray-500">
          End: {dayItems[dayItems.length - 1] ? dayItems[dayItems.length - 1].toLocaleDateString() : '—'}
        </div>
      </div>
    </div>
  );
};

const ProgressDashboard = (props) => {
  const {
    weekStartISO,
    totalEstimatedHoursRemaining,
    courseSummaries,
    weeklyScheduleLines,
    badgeLabels,
  } = props;

  const formattedWeekStart = React.useMemo(() => {
    if (!weekStartISO) return 'Unknown start date';
    const d = new Date(weekStartISO);
    if (isNaN(d.getTime())) return 'Invalid date';
    return d.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric', year: 'numeric' });
  }, [weekStartISO]);

  const hoursRemainingText = React.useMemo(() => {
    const n = Number(totalEstimatedHoursRemaining);
    if (isNaN(n)) return '—';
    if (n < 0) return '0';
    return n.toFixed(n % 1 === 0 ? 0 : 1);
  }, [totalEstimatedHoursRemaining]);

  const safeCourses = Array.isArray(courseSummaries) ? courseSummaries : [];
  const safeSchedule = Array.isArray(weeklyScheduleLines) ? weeklyScheduleLines : [];
  const safeBadges = Array.isArray(badgeLabels) ? badgeLabels : [];

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-lg shadow-sm border border-gray-200 p-6">
      <div className="flex items-start justify-between">
        <div>
          <div className="text-sm text-gray-500">Week starting</div>
          <div className="text-lg font-semibold text-gray-900">{formattedWeekStart}</div>
        </div>
        <div className="flex items-center space-x-2">
          <span className="px-3 py-1 text-xs font-medium rounded-full bg-blue-50 text-blue-700 border border-blue-200">
            Hours remaining
          </span>
          <span className="text-lg font-semibold text-blue-700">{hoursRemainingText}</span>
        </div>
      </div>

      <div className="mt-4">
        <div className="flex flex-wrap gap-2">
          {safeBadges.length > 0 ? (
            safeBadges.map((label, idx) => (
              <span
                key={idx}
                className="px-2.5 py-1 text-xs font-medium rounded-full bg-green-50 text-green-700 border border-green-200"
                title={label}
              >
                {label}
              </span>
            ))
          ) : (
            <div className="text-sm text-gray-500">No badges to display</div>
          )}
        </div>
      </div>

      <div className="mt-6 grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="col-span-1">
          <div className="p-4 bg-gray-50 rounded-lg border border-gray-200">
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-lg font-semibold text-gray-900">Courses</h3>
              <span className="text-xs text-gray-500">{safeCourses.length.toLocaleString()} total</span>
            </div>
            <div className="space-y-2">
              {safeCourses.length > 0 ? (
                safeCourses.map((text, index) => (
                  <div
                    key={index}
                    className="p-3 bg-white rounded-md border border-gray-200 hover:shadow-md transition-shadow"
                  >
                    <div className="flex">
                      <div className="mr-3 flex-shrink-0">
                        <div className="w-10 h-10 rounded-md bg-blue-50 border border-blue-100 flex items-center justify-center text-blue-600 text-sm font-semibold">
                          {String(index + 1).padStart(2, '0')}
                        </div>
                      </div>
                      <div>
                        <div className="text-sm font-medium text-gray-900 line-clamp-2">
                          {text || 'No description'}
                        </div>
                        <div className="text-xs text-gray-500 mt-1">Course summary</div>
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <div className="p-4 bg-white rounded-md border border-dashed border-gray-300 text-sm text-gray-500">
                  <span role="img" aria-label="empty">📚</span> No courses to display
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="col-span-1">
          <div className="p-4 bg-gray-50 rounded-lg border border-gray-200">
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-lg font-semibold text-gray-900">Weekly Schedule</h3>
              <span className="text-xs text-gray-500">{safeSchedule.length.toLocaleString()} items</span>
            </div>
            <div className="space-y-2">
              {safeSchedule.length > 0 ? (
                safeSchedule.map((line, index) => (
                  <div
                    key={index}
                    className="p-3 bg-white rounded-md border border-gray-200 flex items-start hover:shadow-md transition-shadow"
                  >
                    <div className="mt-0.5 w-2 h-2 rounded-full bg-green-500 mr-3"></div>
                    <div className="text-sm text-gray-800 line-clamp-2">
                      {line || 'No details'}
                    </div>
                  </div>
                ))
              ) : (
                <div className="p-4 bg-white rounded-md border border-dashed border-gray-300 text-sm text-gray-500">
                  <span role="img" aria-label="calendar">🗓️</span> No schedule items
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <div className="mt-6 p-4 bg-white rounded-lg border border-gray-200">
        <div className="flex items-center justify-between">
          <div className="text-sm text-gray-600">
            Progress overview for the week
          </div>
          <div className="flex items-center space-x-3">
            <div className="flex items-center space-x-1">
              <span className="w-2 h-2 rounded-full bg-green-500"></span>
              <span className="text-xs text-gray-600">Scheduled</span>
            </div>
            <div className="flex items-center space-x-1">
              <span className="w-2 h-2 rounded-full bg-blue-500"></span>
              <span className="text-xs text-gray-600">Planned</span>
            </div>
          </div>
        </div>
        <div className="mt-3 h-2 w-full bg-gray-100 rounded-full overflow-hidden">
          <div className="h-full bg-blue-500" style={{ width: '60%' }}></div>
        </div>
        <div className="mt-2 text-xs text-gray-500">
          Visualization is illustrative based on planned workloads.
        </div>
      </div>
    </div>
  );
};
